<script setup lang="ts">
import { computed } from 'vue'
import Icon from './Icon.vue'
import type { DataRow } from '../types'
const props=defineProps<{modelValue:DataRow[]}>()
const emit=defineEmits<{'update:modelValue':[rows:DataRow[]];toast:[message:string]}>()
const total=computed(()=>props.modelValue.reduce((a,b)=>a+b.value,0)),max=computed(()=>Math.max(1,...props.modelValue.map(r=>Math.abs(r.value)))),growth=computed(()=>{const first=props.modelValue[0]?.value||0,last=props.modelValue.at(-1)?.value||0;return first===0?'—':((last-first)/Math.abs(first)*100).toFixed(1)+'%'})
function update(i:number,key:'label'|'value',event:Event){const value=(event.target as HTMLInputElement).value;const rows=props.modelValue.map(r=>({...r}));if(key==='value'){if(!Number.isFinite(Number(value)))return;rows[i]!.value=Number(value)}else rows[i]!.label=value;emit('update:modelValue',rows)}
function download(data:string,name:string,type:string){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);emit('toast','已导出 '+name)}
function csv(){const safe=(s:string)=>'"'+(/^[=+\-@\t\r]/.test(s)?"'"+s:s).replaceAll('"','""')+'"';download('\ufeff项目,数值\n'+props.modelValue.map(r=>safe(r.label)+','+r.value).join('\n'),'数据.csv','text/csv;charset=utf-8')}
function escape(s:string){return s.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]!))}
function svg(){const data=props.modelValue.map((r,i)=>`<rect x="${80+i*130}" y="${280-Math.abs(r.value)/max.value*200}" width="68" height="${Math.abs(r.value)/max.value*200}" rx="5" fill="#368b73"/><text x="${114+i*130}" y="305" text-anchor="middle" font-size="15">${escape(r.label)}</text><text x="${114+i*130}" y="${268-Math.abs(r.value)/max.value*200}" text-anchor="middle" font-size="16">${r.value}</text>`).join('');download(`<svg xmlns="http://www.w3.org/2000/svg" width="${Math.max(540,props.modelValue.length*130+110)}" height="350"><rect width="100%" height="100%" fill="white"/><text x="40" y="38" font-family="sans-serif" font-size="20">数值</text><g font-family="sans-serif" fill="#34443f">${data}</g></svg>`,'图表.svg','image/svg+xml')}
</script>
<template><div class="table-result"><div class="result-label"><span><Icon name="table" :size="16"/>数据校对</span><span class="muted">点击单元格编辑</span></div><table><thead><tr><th>项目</th><th>数值</th></tr></thead><tbody><tr v-for="(row,i) in modelValue" :key="i"><td><input :value="row.label" :aria-label="'第'+(i+1)+'行项目'" @change="update(i,'label',$event)" maxlength="80"/></td><td><input type="number" :value="row.value" :aria-label="'第'+(i+1)+'行数值'" @change="update(i,'value',$event)"/></td></tr></tbody></table><div class="table-stat"><span>合计<strong>{{total.toLocaleString()}} </strong></span><span>首末项变化<strong>{{growth}}</strong></span></div><div class="chart-title"><span>数值对比</span><small>随数据同步更新</small></div><div class="bar-chart"><div class="bar-item" v-for="(row,i) in modelValue" :key="i"><span>{{row.value}}</span><div :style="{height:Math.abs(row.value)/max*120+'px'}"/><small>{{row.label}}</small></div></div><div class="result-footer"><span><i/>已同步图表</span><button @click="csv"><Icon name="download" :size="14"/>CSV</button><button @click="svg"><Icon name="download" :size="14"/>图表</button></div></div></template>
